// protocol:begin
// @generated by `task protocol:generate` from protocol/protocol.schema.json. DO NOT EDIT.

// deps の stdin。欄は無く {} を渡す (読み手はどのセッションにも属さない)
export type DepsRequest = {
}

// park add の stdin。memo を置き、ParkAdded を出す
export type ParkAddRequest = {
  // 置いたセッションの cwd。repo をここから決める (無ければ今の cwd)
  cwd?: string
  // 置いたセッションの ID
  session_id: string
  memo: Memo
}

// park set の stdin。メモの status を書き換え、ParkingItem を出す。handed にするときは宛先を to_session か to_repo で渡し、handed 以外にすると宛先を空にする。依存図の pane は渡す前に status handed、from open と宛先で取り、届かなければ status open、from handed で戻す
export type ParkSetRequest = {
  // メモの id
  id: string
  status: 'open' | 'handed' | 'discarded'
  // 今の status がこれのときだけ書き換える。違えば書き換えずにエラーで返す
  from?: 'open' | 'handed' | 'discarded'
  // handed にするときの宛先のセッションの ID
  to_session?: string
  // handed にするときの宛先 (新しく起こすセッションの repo の絶対パス)
  to_repo?: string
  // 操作したセッションの ID (ログに添える)
  session_id?: string
}

// park list の stdin。絞ったメモを ParkingItemList で出す
export type ParkListRequest = {
  // here で使う cwd (無ければ今の cwd)
  cwd?: string
  // cwd の repo で絞る
  here?: boolean
  // repo (main worktree のパス) で絞る
  repo?: string
  // status で絞る
  status?: 'open' | 'handed' | 'discarded'
  // session_id のセッションがこのタスクの途中で置いたメモで絞る
  task?: string
  // task で絞るセッションの ID
  session_id?: string
}

// park discard の stdin。最後に置かれてから days 日より経った open のメモを discarded にし、捨てたメモを ParkingItemList で出す
export type ParkDiscardRequest = {
  days: number
  // 操作したセッションの ID (ログに添える)
  session_id?: string
}

// park withdraw の stdin。session_id のセッションだけが置いた open のメモを discarded にし、ParkingItem を出す。park tool の unpark が呼ぶ。ほかのセッションも置いたメモと open でないメモは書き換えずに exit 1 で理由を返す
export type ParkWithdrawRequest = {
  // メモの id
  id: string
  // 取り下げるセッションの ID。メモの sources のセッションがすべてこれのときだけ通す
  session_id: string
}

// park adopt の stdin。終了したセッションの未完了のタスク (task:) か、タスクの無いセッションの作業 (sid:) を出自 adopted (種類 scope) のメモにし、その記録を消して ParkAdded を出す。セッションの終了は、動いている daemon が記録より後に書いた status.json に pane が無いことで確かめる
export type ParkAdoptRequest = {
  // 依存図のノードの key (task:<session_id>/<task_id> か sid:<session_id>)
  ref: string
  // 操作したセッションの ID (ログに添える)
  session_id?: string
}

// work set の stdin。セッションの作業の記録の題を書き換え、Work を出す。subject は人が直した題 (出どころ human。以後の hook と companion は書き換えない)、inferred は companion の推定の題 (subject とは別の欄で、人が直していなければこちらを見せる)。どちらか 1 つ以上。記録が無ければ exit 1
export type WorkSetRequest = {
  // 作業のセッションの ID
  session_id: string
  // 人が直した題
  subject?: string
  // companion の推定の題
  inferred?: string
}

// work get の stdin。セッションの作業の記録を Work で出す。無ければ exit 1
export type WorkGetRequest = {
  // 作業のセッションの ID
  session_id: string
}

// セッション 1 つの作業の記録 (work get、work set の出力)。hook が書く事実 (最初の prompt の題、最後のターンの要約、turns、最後の prompt と Stop の時刻、始まりと終わり) と、人の直した題、companion の推定の題
export type Work = {
  session_id: string
  cwd: string
  // 題 (出どころは origin)
  subject?: string
  // 題の出どころ。prompt は最初の prompt の 1 行目、human は人が work set で直した
  origin?: 'prompt' | 'human'
  // companion の推定の題
  inferred?: string
  // 最後のターンの応答の 1 行目
  summary?: string
  // UserPromptSubmit の数 (peer の delivery も数える)
  turns: number
  started_at: string
  updated_at: string
  // 最後の UserPromptSubmit の時刻
  prompted_at?: string
  // 最後の Stop の時刻
  stopped_at?: string
  // SessionEnd の時刻。生きている (resume した) 間は無い
  ended_at?: string
  // SessionEnd の reason
  end_reason?: string
  // このセッションが gh pr create で出した PR の参照 (pr:<owner>/<repo>#<番号>)。daemon が PR からこのセッションへの辺を導くのに使う
  prs?: string[]
}

// park hand の stdin。open のメモを取り (status handed、宛先付き)、文面を組んで宛先へ渡し、届かなければ open に戻す。宛先は生きているセッション (to_session。tell で入力欄に打つ) か、新しく起こすセッションの repo (to_repo。spawn) のどちらか 1 つ。取れなければ (ほかが先に渡した、捨てた) 何もせず exit 1 で理由を返し、取れた後は届かなくても ParkHandResult を出す
export type ParkHandRequest = {
  // メモの id
  id: string
  // 渡した先に頼むこと。task はタスクにする、issue は GitHub の issue にする
  intent: 'task' | 'issue'
  // 宛先のセッションの ID
  to_session?: string
  // 新しく起こすセッションの repo の絶対パス
  to_repo?: string
  // 利用者の補足。文面の末尾に足す
  note?: string
  // 操作した主体 (セッションの ID かアプリの固定の名前。ログに添える)
  session_id?: string
}

// park hand の出力。delivered が false のときは reason に届かなかった理由があり、status が open なら戻してある。新しく起こしたセッションで claude が前景になるのを待ち切れたときは to に起こした session ID、status は handed のまま (戻すと押し直しで 2 つ目が起きる)
export type ParkHandResult = {
  delivered: boolean
  // 渡した後のメモの status
  status: 'open' | 'handed'
  // 届いた (届けようとした) セッションの ID。起こす前に失敗したときは無い
  to?: string
  // 打った (起こした) pane の ID
  pane_id?: string
  // 届かなかった理由。戻せなかったときはその理由も続ける
  reason?: string
}

// task dismiss の stdin。終了したセッションのタスク (完了しているかを問わない。task:) か、セッションの作業 (sid:) の記録と端点の辺を消して依存図から外し、{} を出す。セッションの終了は park adopt と同じく status.json で確かめ、確かめられなければ消さずに exit 1 で理由を返す
export type TaskDismissRequest = {
  // 依存図のノードの key (task:<session_id>/<task_id> か sid:<session_id>)
  ref: string
  // 操作したセッションの ID (ログに添える)
  session_id?: string
}

// edge add の stdin。before が済まないと after を始められない辺を書き、EdgeAdded を出す。同じ辺の二重登録は書き直すだけ
export type EdgeAddRequest = {
  before: EdgeTarget
  after: EdgeTarget
  // 辺の補足 (何の後か)
  note?: string
}

// edge rm の stdin。辺を消し、EdgeRemoved を出す
export type EdgeRemoveRequest = {
  before: EdgeTarget
  after: EdgeTarget
}

// 書く辺の端点。ref (cwd も要る) か task のどちらか 1 つで指す
export type EdgeTarget = {
  // 作業の参照 (session:<名前> / sid:<session_id> / issue:<owner>/<repo>#<番号> / pr:<owner>/<repo>#<番号> / task:<session_id>/<task_id>)
  ref?: string
  // 書く側のセッション自身のタスクの id。参照はバイナリが task:<CLAUDE_CODE_SESSION_ID>/<id> に組む
  task?: string
  // その作業のセッションの cwd (絶対パス)。task の端点では省くとバイナリの cwd
  cwd?: string
}

// spawn の stdin。prompt を最初のターンにした Claude Code のセッションを、repo を cwd にした新しい rex の session に起こし、SpawnResult を出す
export type SpawnRequest = {
  // 新しいセッションの cwd (絶対パス)
  repo: string
  // 最初のターンとして入る本文
  prompt: string
}

// tell の stdin。to_session のセッションが動いている rex の pane の入力欄に text を打って Enter を送り、TellResult を出す。pane で claude が前景でない、利用者の答えを待つ prompt (permission / question / auth) が開いている、上限の画面、入力欄に打ちかけの文がある、のどれかなら送らずに exit 1 で理由を返す。文面を打った後、Enter の前に claude が前景でなくなるか prompt が開いたら、Enter を送らずに exit 1 で理由を返し、文面は入力欄に残る。ターンの途中の pane には送り、文面は入力欄に溜まって次のターンになる
export type TellRequest = {
  // 宛先のセッションの ID
  to_session: string
  // 入力欄に打つ文面。複数行は 1 回の paste として打つ
  text: string
  // 操作した主体 (セッションの ID かアプリの固定の名前。ログに添える)
  session_id?: string
}

// event-log の stdin。mod の出来事を出来事のログに 1 行書く。出来事の名前と欄は eventlog の package doc が持つ
export type EventLogRequest = {
  // 出来事の起きたセッションの ID
  session_id?: string
  event: string
  // 行に添える欄 (書いた順)
  fields?: EventLogField[]
}

export type EventLogField = {
  key: string
  value: string
}

// パーキングロットに置くメモの中身。park の tool の入力でもある
export type Memo = {
  // メモの種類
  kind: 'aside' | 'scope' | 'preference'
  // メモを 1 行で。同じ repo に同じ title の open のメモがあれば 1 つにまとまる
  title: string
  // 後で取り出した人が文脈を復元できる説明
  detail?: string
  // 関係するファイルのパス (repo からの相対か絶対)。別のセッションがそのファイルを触ったとき、その model に伝わる
  files?: string[]
  // 今どうしたか (「やらない」、仮に決めた内容)
  default_taken?: string
}

// 置かれたメモ 1 つの記録 (park list、park set の出力)
export type ParkingItem = {
  id: string
  // 置いたときの cwd の main worktree のパス (git の外なら cwd)。依存図の repo の鍵と同じ
  repo: string
  kind: 'aside' | 'scope' | 'preference'
  title: string
  detail?: string
  files?: string[]
  default_taken?: string
  // 出自。placed は park の tool で置いたメモ、adopted は終了したセッションの未完了のタスクから移したメモ
  origin: 'placed' | 'adopted'
  sources: ParkingItemSource[]
  status: 'open' | 'handed' | 'discarded'
  // handed にしたときの宛先 (sid:<session_id> / repo:<path>)。handed でなければ無い
  handed_to?: string
}

// メモを置いたときのセッションと、そのとき進行中だったタスク
export type ParkingItemSource = {
  session_id: string
  task_id?: string
  cwd: string
  // 既存のメモにまとめたとき、後から置いた側が書いた detail (メモの detail と違うときだけ)
  detail?: string
  at: string
}

// park list と park discard の出力
export type ParkingItemList = ParkingItem[]

// park add と park adopt の出力。created は新しく作ったか (false なら既に置かれていたメモにまとめた)
export type ParkAdded = {
  created: boolean
  item: ParkingItem
}

// セッションをまたぐ辺の記録 1 つ。derived は daemon が PR の head branch とセッションの branch の一致から導いた sid → pr の辺
export type Edge = {
  id: string
  before: EdgeEndpoint
  after: EdgeEndpoint
  note?: string
  derived?: boolean
  created_at: string
}

// 辺の記録の端点。bound_from は daemon が session:<名前> を sid:<id> に結びつけたときの元の参照
export type EdgeEndpoint = {
  ref: string
  cwd: string
  repo: string
  bound_from?: string
}

// edge add の出力。同じ辺が既にあれば created は false
export type EdgeAdded = {
  created: boolean
  edge: Edge
}

// edge rm の出力。無い辺を消したときは removed が false
export type EdgeRemoved = {
  removed: boolean
  id: string
}

// spawn の出力。foreground が false なら claude が前景になるのを待ち切れず、pane は残り claude が起きているかもしれない。呼び出し側はメモを戻さず detail を人に見せる
export type SpawnResult = {
  session_id: string
  pane_id: string
  foreground: boolean
  detail?: string
}

// tell の出力。送れたときだけ出る (送らなかったときは exit 1)
export type TellResult = {
  // 打った pane の ID
  pane_id: string
}

// deps の出力。依存の DAG と、repo ごとの生きているセッションと open のメモ
export type DepsData = {
  daemon_running: boolean
  // status.json の更新時刻。daemon が動いていないか、まだ書いていなければ無い
  updated_at?: string
  // open のメモを「古い」とみなす日数。アプリはこれより前に最後に置かれたメモをまとめて捨てるボタンを出す
  stale_memo_days: number
  repos: DepsRepo[]
  // セッション台帳に載った repo。最後に見た時刻の新しい順 (新しいセッションを起こす repo の候補)
  recent_repos: RecentRepo[]
  graph: DepsGraph
}

// 台帳のセッションが最近動いた repo 1 つ
export type RecentRepo = {
  // 鍵 (DepsRepo.repo と同じ規則)
  repo: string
  title: string
  // その repo のセッションを最後に見た時刻
  last_seen: string
}

// repo 1 つ。sessions は表示名の順、memos は open のメモを置いた順
export type DepsRepo = {
  // 鍵 (main worktree のパス、git の外なら cwd)。パーキングのメモの repo と同じ規則
  repo: string
  title: string
  // origin が GitHub のときの owner/repo。本文の #123 をリンクにする材料
  github_repo?: string
  sessions: DepsSession[]
  memos: ParkingCard[]
}

// repo で生きているセッション 1 つ (メモを渡す宛先)
export type DepsSession = {
  session_id: string
  // 表示名 (同名のセッションがあれば session ID の先頭が付く)
  session: string
  // そのセッションが何をしているか
  subject: string
  live: boolean
}

// repo の open のメモ 1 つ
export type ParkingCard = {
  id: string
  kind: 'aside' | 'scope' | 'preference'
  origin: 'placed' | 'adopted'
  title: string
  detail?: string
  files?: string[]
  default_taken?: string
  // 置いたセッションの新しい順
  sources: ParkingSource[]
}

// メモを置いたセッション 1 つ
export type ParkingSource = {
  session_id: string
  // 置いたときに進めていたタスクのノードの key (GraphNode.key と同じ Ref)
  task_ref?: string
  session: string
  live: boolean
  // まとめたときに後から置いた側が書いた detail
  detail?: string
  at: string
}

// タスクの依存の DAG
export type DepsGraph = {
  // 下流の多い順 (同じなら key の順)
  nodes: GraphNode[]
  links: GraphLink[]
  // 下流の最も多い止まっているノードから、下流をたどった最長の鎖の key
  longest_chain: string[]
  folded: FoldedGraph
  // folded の nodes と、links のうち両端が folded の nodes にあるものと folded の links で組んだレーンの行
  rows: GraphRow[]
  // 完了したノードも含めて組んだレーンの行
  rows_with_completed: GraphRow[]
  // 依存の無いノードを図の領域のセッションの枠と右の列に並べる順 (全ノードの key)。手当てが要るもの、作業中、返事待ち、未着手、外部の参照、完了、終了の段で、同じ段は最後に動いた時刻の新しい順
  column_order: string[]
}

// 依存の DAG のノード 1 つ (タスク 1 つ、タスクか進行中の作業の無いセッションの作業、端点の参照だけの置き場)
export type GraphNode = {
  // Ref (task:、todo:、sid:、session:、issue:、pr:)。mod は切り出さずに不透明な文字列として扱う
  key: string
  kind: 'task' | 'todo' | 'session' | 'ref'
  // external は daemon がまだ状態を引けていない外部の参照 (issue / PR)。daemon が open と引けた参照は waiting、merged の PR、completed で閉じた issue と引けた参照は completed、マージせずに閉じた PR、not planned / duplicate で閉じた issue は dropped (取りやめ)
  state: 'working' | 'done' | 'unknown' | 'question' | 'permission' | 'error' | 'limit' | 'pending' | 'completed' | 'exited' | 'external' | 'waiting' | 'dropped'
  // ノードの題。issue: / pr: の置き場は daemon が引いた題で、引けていなければ番号と repo
  title: string
  // kind session のノードの題の出どころ。prompt は最初の prompt、inferred は companion の推定 (推定と分かるように見せる)、human は人が直した、pane は作業の記録が無く pane の名前から付けた
  origin?: 'prompt' | 'inferred' | 'human' | 'pane'
  // issue: / pr: の置き場のノードの参照の種類
  ref_kind?: 'issue' | 'pr'
  // issue: / pr: の置き場のノードの番号と repo (「PR #389 · owner/repo」)。題を引いた後も番号を読めるように残す
  ref_label?: string
  // open の PR の段。次に手を動かすものから順で、先頭を箱に出す。段を引いていない PR と open でない参照には付かない
  pr_stages?: ('ci_failing' | 'conflicting' | 'draft' | 'changes_requested' | 'review_required' | 'ci_running' | 'behind' | 'mergeable' | 'ci_passing' | 'approved')[]
  // セッションの今の作業。生きていれば Claude Code が申告したもの (OSC 7501 の msg)、終了していれば最後のターンの応答の 1 行目 (作業の記録)。kind session のノードと、進行中のタスクと TodoWrite の項目のノードに付く
  summary?: string
  // 状態の補足 (上限の解除時刻)
  detail?: string
  // key をそのまま edge add の端点に書けるか (TodoWrite の項目は書けない)
  endpoint: boolean
  cwd?: string
  // cwd の repo の鍵 (DepsRepo.repo と同じ規則)
  repo?: string
  // kind task のノードのタスクの ID (TaskUpdate に書く形)
  task_id?: string
  // kind task のノードのタスクの description
  description?: string
  session_id?: string
  // 表示名 (同名のセッションがあれば session ID の先頭が付く)
  session?: string
  // ListAgents の名前 (SendMessage の宛先に書く形)。表示名とは別
  session_name?: string
  live: boolean
  // 段 (前提をたどった最長の深さ)
  depth: number
  // 下流 (このノードが済まないと始められないノード) の数
  downstream: number
  // このタスクの途中で置かれた open のメモの数
  parked: number
  // このタスクの description に id が書かれたメモ (書かれた順)。status を問わない
  memos: MemoRef[]
  // 上流をたどった原因の鎖 (近い順)
  blocked_by: string[]
  // 待ちが輪になっていて、たどると自分へ戻ってくるか
  deadlock: boolean
  // セッション自身が止まっているか (question、permission、limit、error)
  halted: boolean
  // 止まっているノードか (halted か、完了していない待ちの輪)。mod は状態の語から決めない
  stuck: boolean
}

// タスクが扱うメモ 1 つ
export type MemoRef = {
  id: string
  title: string
  status: 'open' | 'handed' | 'discarded'
}

// 辺 1 本。kind task は同じセッションの blockedBy、kind edge は edge add で書かれた辺で edge に元の記録を持つ
export type GraphLink = {
  before: string
  after: string
  kind: 'task' | 'edge'
  edge?: EdgeRecord
}

// 完了したノードを隠したときの図。隠したノードを通り抜けていた辺は畳んで残す
export type FoldedGraph = {
  // 見せるノード (DepsGraph.nodes の順)。完了していないものと、完了していても下流に完了していないノードが無く、完了も終了もしていない上流を直接持つもの
  nodes: FoldedNode[]
  // 隠したノードを通り抜けた辺。両端が nodes にあり、同じ組の辺が DepsGraph.links に無いもの
  links: FoldedLink[]
}

// 完了したノードを隠した図に見せるノード 1 つ
export type FoldedNode = {
  key: string
  // この図の辺 (両端が見える辺と畳んだ辺) で数え直した段。数え方は GraphNode.depth と同じ
  depth: number
}

// 隠したノードを通り抜けた経路を畳んだ辺 1 本
export type FoldedLink = {
  before: string
  after: string
  // 通り抜けた隠したノードの key (経路の順)
  via: string[]
}

// kind edge の辺の元の記録。edge rm に渡す
export type EdgeRecord = {
  id: string
  before: EdgeEndpoint
  after: EdgeEndpoint
  // edge add で書いた辺の補足。daemon が引いた issue / PR の題は混ぜない (参照のノードの題に出る)
  note?: string
}

// レーンの行 1 つ。lanes は行頭の罫線で、ノードの行は * がそのノードのレーンの位置。node が無ければ辺をつなぐだけの行
export type GraphRow = {
  lanes: string
  node?: string
  // longest chain の辺を描いた lanes の桁 (昇順)
  marks?: number[]
}

// protocol:end

declare module 'claude-code' {
  interface PluginState {
    'agents-daemon': {
      // deps は最後に読めた依存図 (deps-data.ts)。読めていなければ null。
      deps: DepsData | null
      // error は直近の読み込みの失敗理由。読めたら空にする。
      error: string
      // told はファイルを触った tool の結果で model に伝えたメモの id (hooks/notice.ts)。同じメモを 2 度伝えない。
      // main の会話が compact されたら空にする。
      told: string[]
      // logged は出来事のログに slot ごとに最後に書いた中身 (hooks/log.ts)。同じものを書き直さないため。
      logged: Record<string, string>
      // inferDue は main のターンが終わってから companion の timer がまだ見ていない印 (hooks/work-infer.ts)。
      inferDue: boolean
      // inferAttempts はこのセッションで companion が推定を起こした回数。上限で止まる。
      inferAttempts: number
    }
  }
}
